def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    # Split the string into chunks of digits and non-digits
    chunks = [chunk for chunk in s.split('-') if chunk.strip()]

    # Convert each chunk to an integer, if possible
    versions = []
    for chunk in chunks:
        if chunk.strip().isdigit():
            versions.append(int(chunk))
        else:
            versions.append(0)

    # Pad the list with zeros to the same length
    while len(versions) < len(chunks):
        versions.append(0)

    return tuple(versions)

