class MemoryCache:
    def __init__(self, maxsize=128, ttl=600, timer=time.monotonic, typed=False):
        self.cache = dict()
        self.maxsize = maxsize
        self.ttl = ttl
        self.timer = timer
        self.ttl_callback = lambda: None


    def ttl_callback(self):
        del self.cache[self._get_expired_items()]


    def _get_expired_items(self):
        expired_items = []
        current_time = self.timer()
        for val, key in self.cache.items():
            if current_time - key['timestamp'] >= self.ttl:
                expired_items.append(key)
        return expired_items

    def __getitem__(self, key):
        # Implement LRU algorithm with TTL to provide non-synchronized dictionary
        value = self.cache[key][0]
        self.cache[key]['timestamp'] = self.timer()
        self.ttl_callback()
        return value


    def __setitem__(self, key, value):
        # Implement LRU algorithm with TTL to provide non-synchronized dictionary
        if key in self.cache:
            key['timestamp'] = self.timer()
        else:
            if len(self.cache) >= self.maxsize:
                expired_items = self._get_expired_items()
                for item in expired_items:
                    del self.cache[item[0]]
        self.cache[key] = [value, self.timer()]


    def __delitem__(self, key):
        if key in self.cache:
            del self.cache[key]


    def __iter__(self):
        return self.cache.keys().__iter__()

    def __len__(self):
        return len(self.cache)

