class TTLCache:
    def __init__(self, maxsize=128, ttl=600, timer=time.monotonic, typed=False):
        """Decorator to wrap a function with a memoizing callable that saves
        up to `maxsize` results based on a Least Recently Used (LRU)
        algorithm with a per-item time-to-live (TTL) value.
        """
        self.maxsize = maxsize
        self.ttl = ttl
        self.timer = timer
        self.ttl_items = OrderedDict()
        self.cache = {}
        self.ttl_cache = {}

    def __getitem__(self, key):
        if key in self.ttl_items:
            value, ttl = self.ttl_items[key]
            if self.timer() - ttl > self.ttl:
                raise KeyError(key)
            self.ttl_items.pop(key)
            self.ttl_items[key] = (value, self.timer())
        if key in self.cache:
            return self.cache[key]
        raise KeyError(key)

    def __setitem__(self, key, value):
        if len(self.ttl_items) >= self.maxsize:
            oldest_key, oldest_ttl = next(iter(self.ttl_items.items()))
            if oldest_ttl - self.timer() > self.ttl:
                del self.ttl_items[oldest_key]
                del self.cache[oldest_key]
        self.ttl_items[key] = (value, self.timer())
        self.cache[key] = value

    def __delitem__(self, key):
        if key in self.ttl_items:
            del self.ttl_items[key]
        if key in self.cache:
            del self.cache[key]

    def __contains__(self, key):
        return key in self.ttl_items or key in self.cache

    def __len__(self):
        return len(self.ttl_items) + len(self.cache)

    def clear(self):
        self.ttl_items.clear()
        self.cache.clear()
        self.ttl_cache.clear()

    def keys(self):
        return self.ttl_items.keys() + self.cache.keys()

    def values(self):
        return self.ttl_items.values() + self.cache.values()

