        def wrapper(*args, **kwargs):
            key = self.key(args, kwargs)
            if key in self.caches:
                node = self.caches[key]
                if node.ref() is None:
                    del self.caches[key]
                node.usage += 1
                self.usage_order.move_to_end(node)
                return node.value
