                return result

        return wrapper

    def key(self, args, kwargs):
        return hash((self.typed, args, kwargs))

    def is_fresh(self, key):
        return hash(self.typed, args, kwargs) in self.caches

    def incr_usage(self, order):
        for key, node in self.caches.items():
            if node.usage > 0:
                if node.ref() is None:
                    del self.caches[key]
                else:
                    node.usage += 1
                    order.move_to_end(node)

