def minimalBases(classes):
    seen = set()
    queue = [c for c in classes]

    while queue:
        c = queue.pop(0)
        if c not in seen:
            seen.add(c)
            queue.extend([sup for sup in c.superclasses if sup not in seen])

    return sorted(seen)

