def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """

    if not hasattr(self, "properties"):
        # If the graph does not have properties, set error and return
        context.error.append("Graph without properties")
        return

    properties = self.properties

    # Append properties to the context
    for key, value in properties.items():
        if isinstance(value, (list, dict)):
            context[key] = value
        else:
            context[key] = {"value": value}

    # Update object IDs in context value
    for object_id, object_properties in properties.items():
        if "OCCURS" in object_properties:
            object_properties["OCCURS"] = len([prop for prop in properties.values() if prop["OCCURS"] == object_properties["OCCURS"]])

    # Update elements in context value
    for element_id, element in properties.items():
        if "ELEMENTS" in element:
            element_properties = element["ELEMENTS"]
            for element_name, element_data in element_properties.items():
                context[element_name] = element_data
        if "RELATIONSHIPS" in element:
            element_properties = element["RELATIONSHIPS"]
            for relationship_name, relationship_data in element_properties.items():
                context[relationship_name] = relationship_data

