                errors.append({"key": key, "value": "expected string or bytes-like object"})
        elif isinstance(value, list):
            for i, val in enumerate(value):
                if isinstance(val, str) and not self._symbols_regex.match(val):
                    errors.append({"key": key, "value": f"expected string or bytes-like object at index {i}"})
