                value = value.encode('utf-8')
                if value != value.encode('ASCII'):
                    raise ValidationError({
                        key: 'expected string or bytes-like object'
                    })
            assert isinstance(value, str) or isinstance(value, bytes)
        except UnicodeEncodeError:
            raise ValidationError({
                key: 'expected string or bytes-like object'
            })

    if '$$' in labels and not re.match(R'[^@#$%&*()_+{}[\];:@<>?,./^`\|~\"]*', labels['$$']):
        raise ValidationError({
            '$$': "Label key '$$' does not match the regex [...]"
        })

    for value in labels.values():
        if isinstance(value, dict):
            value = {}
            otherkeys = set(value) - set([key for key in value if key == key])
            for key, val in value.items():
                if isinstance(key, str):
                    key = key.encode('utf-8')
