                            key: 'expected string or bytes-like object'
                        })
                else:
                    raise ValidationError({
                        key: 'expected string or bytes-like object'
                    })

                if val not in ({'valid': True}, {'valid': False}, True, False):
                    raise ValidationError({
                        key: 'expected string or bytes-like object'
                    })
        else:
            raise ValidationError({
                key: 'expected string or bytes-like object'
            })

