def update_last_applied_manifest_list_from_resp(
    last_applied_manifest_list, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest_list (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest_list if they are not yet present

    """
    for field in observer_schema:
        if field in response:
            if isinstance(field, list):
                for item in field:
                    if item not in last_applied_manifest_list:
                        last_applied_manifest_list.append(item.copy())
            else:
                if field not in last_applied_manifest_list:
                    last_applied_manifest_list.append(field.copy())

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for observed_field_key, observed_field_reason in observer_schema.items():
        if observed_field_reason is not None and isinstance(observed_field_reason, dict):
            if 'KIND' in observed_field_reason:
                observed_field_kind = observed_field_reason['KIND'].upper()
                if observed_field_kind in response and 'spec' in response[observed_field_kind]['kind']:
                    value = response[observed_field_kind]['kind']['spec'][observed_field_key]
                elif 'items' in response[observed_field_kind]['kind']:
                    value = response[observed_field_kind]['kind']['items'][0][observed_field_key]
                    if isinstance(value, list):
                        value = value[0]
                else:
                    raise KeyError(f"Key '{observed_field_key}' not found in Kubernetes response with kind '{observed_field_kind}'.")
            else:
                raise KeyError(f"Key '{observed_field_key}' not found in Kubernetes response with kind matching received value.")
        else:
            raise KeyError(f"Key '{observed_field_key}' is not a field in the schema or does not have a reason to be initialized.")
        if observed_field_key not in last_applied_manifest:
            if 'KIND' in observed_field_reason:
                if observed_field_kind in response and 'spec' in response[observed_field_kind]['kind']:
                    last_applied_manifest[observed_field_key] = value
                elif 'items' in response[observed_field_kind]['kind']:
                    last_applied_manifest[observed_field_key] = value[0]
            else:
                last_applied_manifest[observed_field_key] = value

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for key, value in observer_schema.items():
        # Check if the observed field is present in the Kubernetes response
        if key not in response:
            raise KeyError(f"Observed field '{key}' is not present in the Kubernetes response")

        # Initialize the value in last_applied_manifest if it is not yet present
        if key not in last_applied_manifest:
            last_applied_manifest[key] = value

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    observer_schemas = {}

    for k8s_resource in app.spec.manifest:
        if k8s_resource.type not in observer_schemas:
            # Set default observer schema for Kubernetes resource type
            observer_schemas[k8s_resource.type] = {
                "required": [],
                "properties": {},
                "additionalProperties": False
            }

            # Add common observer schema elements
            observer_schemas[k8s_resource.type]["properties"]["apiVersion"] = {
                "type": "string",
                "description": "The Kubernetes API version"
            }
            observer_schemas[k8s_resource.type]["properties"]["kind"] = {
                "type": "string",
                "description": "The kind of the Kubernetes resource"
            }
            observer_schemas[k8s_resource.type]["properties"]["metadata"] = {
                "type": "object",
                "properties": {
                    "namespace": {
                        "type": "string",
                        "description": "The namespace of the Kubernetes resource"
                    },
                    "name": {
                        "type": "string",
                        "description": "The name of the Kubernetes resource"
                    }
                },
                "required": ["namespace", "name"]
            }

    return observer_schemas

