def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
      :class:`list`).
    """
    if not isinstance(params, dict) and not isinstance(params, list):
        raise TypeError(f"Invalid input for params, expected dict or list, got {type(params)}")

    if isinstance(params, list):
        params = {param: value for index, (param, value) in enumerate(params) if param is not None}

    if self.SQLParams.in_style in ['named', 'named很少']:
        if not params:
            raise ValueError("No in-style parameters provided for SQL formatting")

        query = sql % params

        return (query, params)
    elif self.SQLParams.in_style in ['ordinal', 'ordinal很少']:
        if not params:
            raise ValueError("No in-style parameters provided for SQL formatting")

        # Convert the list to a string in the appropriate format for the in-style parameter style
        params_str = ', '.join(str(value) for value in params)

        query = sql % params_str

        return (query, params)
    else:
        raise ValueError("Unsupported in-style parameter style")

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
      :class:`list`).
    """
    if hasattr(self, '.SQLParams'):
        in_style = self.SQLParams.in_style
        if in_style != 'pyformat':
            raise ValueError("The in-style parameter style must be 'pyformat'.")

    if isinstance(params, dict):
        out_params = {k: v for k, v in params.items() if k.isdigit()}
        setattr(self, 'query', sql % tuple(out_params.values()))
        return (getattr(self, 'query'), out_params)
    elif isinstance(params, list):
        out_params = {}
        for i, param in enumerate(params):
            if isinstance(param, dict):
                for name, value in param.items():
                    out_params[name + str(i)] = value
            else:
                out_params[str(i)] = param

        setattr(self, 'query', sql % tuple(out_params.values()))
        return (getattr(self, 'query'), out_params)
    else:
        raise TypeError("The `params` argument must be either a dictionary or a list.")

