        raise ValueError("Manifest is not set for this element.")

    for indicated_digest in digests_used:
        manifest_entries = self.manifest.get(indicated_digest)
        if not manifest_entries:
            raise ValueError(f"Digest '{indicated_digest}' is not present in the manifest.")

        # Check if all digests in used are in the manifest
        if not set(digests_used).issubset(set(manifest_entries)):
            raise ValueError(f"Digests in used list are not present in the manifest.")

        # Check if all digests in the manifest are used
        if not set(manifest_entries).issubset(set(digests_used)):
            raise ValueError(f"Not all digests in the manifest are used.")

