def absorb(self, args):
    """Given an `args` sequence of expressions, return a new list of expression applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_expr = []
    for expr in args:
        new_expr.extend([Expression(method="Absorption")
                        if Expression(expr.method == "Either")
                        else Expression(expr.method + ", NegativeAbsorption")
                        for expr in split(expr, '|')])
    return concatenate(new_expr)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for a in args:
        if isinstance(a, (BinaryExpression, UnaryExpression)):
            if a.isAbsorbed:
                result.append(a)
        elif isinstance(a, BinaryExpression):
            result.append(a)
        elif isinstance(a, UnionExpression):
            if a.isAbsorbed:
                result.append(a)
            elif isinstance(a, NegationExpression):
                for child in a.children:
                    if isinstance(child, UnionExpression):
                        if child.isAbsorbed:
                            result.append(a)
            elif isinstance(a, UnionExpression):
                for child in a.children:
                    if isinstance(child, NegationExpression):
                        for greatchild in child.children:
                            if isinstance(greatchild, UnionExpression):
                                if greatchild.isAbsorbed:
                                    result.append(a)
    return result

