        if e.returncode > 0:
            print(f"Command failed with exit code {e.returncode}")
        if verbose:
            print(e.output)

import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]

    proc_args = {'cmd': commands, 'args': args}

    if cwd:
        proc_args['cwd'] = cwd

    if verbose:
        proc_args['stdout'] = subprocess.PIPE
        proc_args['stderr'] = subprocess.STDOUT

    if hide_stderr:
        proc_args['stderr'] = subprocess.PIPE

    if env:
        proc_args['env'] = env

    try:
        process = subprocess.Popen(**proc_args)
        stdout, stderr = process.communicate()
        return {'stdout': stdout, 'stderr': stderr, 'return_code': process.returncode}
    except Exception as e:
        return {'error': str(e)}

