        num_objects = 0
        good_objects = 0

        root_elements = [elem for elem in self if elem.is_root_element()]

        if check_digests:
            digests = [elem.digest for elem in root_elements]
            digests.sort()

            if digests != list(range(len(root_elements))):
                if show_warnings:
                    print(f"Detected digests out of expected order: {digests}")
                return num_objects, good_objects, False

        for elem in root_elements:
            try:
