    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    if show_warnings:
        warnings.warn("Validating hierarchy within the object")

    # iterate over all entities in the hierarchy
    for entity in self.collect_entities(entity_type=AbstractElement):
        num_objects += 1

        if validate_objects:
            if not entity.validate():
                if show_warnings:
                    warnings.warn("Entity validation failed for " + entity.id)
