def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return '1'

    parts = version.split('.')
    if len(parts) == 1:
        leading_zeros = len(parts[0])
    else:
        leading_zeros = max(len(parts[0]), len(parts[1]))

    return f'{leading_zeros * "0"}1'

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
        if version.endswith('.0'):
            # find the last integer part
            return str(int(version[:-2]) + 1) + '.0'
        else:
            # remove the last character and increase the integer part by 1
            return version[:-1] + str(int(version[-1]) + 1)

