def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """

    root_inventory = self.get_root_inventory()
    if not root_inventory:
        raise ValueError("No root inventory available")

    digests = {}
    for version_dir in version_dirs:
        inventory = self.load_inventory(version_dir)
        if not inventory:
            raise ValueError(f"No inventory available for version {version_dir}")
        for path, digest in inventory.items():
            if path in digests:
                if digest != digests[path]:
                    raise ValueError(f"Different content digest for path {path}")
            else:
                digests[path] = digest

    root_inventory_digests = root_inventory.get_digests()
    mismatch_paths = []
    for path, digest in digests.items():
        if path in root_inventory_digests:
            if digest != root_inventory_digests[path]:
                mismatch_paths.append(path)

    if mismatch_paths:
        raise ValueError(f"Content digest mismatch for paths: {mismatch_paths}")

