    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parser_map = {k: subparsers[k].add_argument_group() for k in subparsers.keys()}
    parsed_args = {}
    remaining_args = []

    for arg in unparsed_arguments:
        for k, parser in parser_map.items():
