    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    merged = defaultdict(lambda: None)
    for key, value in nodes:
        if key is None:
            raise ValueError("Invalid key in the input list: None")
        if isinstance(key, ruamel.yaml.nodes.ScalarNode):
            key_str = key.value
        elif isinstance(key, ruamel.yaml.nodes.MappingNode):
            key_str = ruamel.yaml.dump(key)
        else:
            raise ValueError("Invalid key type: " + type(key).__name__)

        if isinstance(value, ruamel.yaml.nodes.ScalarNode):
            if merged[key_str] is None:
                merged[key_str] = value
            else:
                logging.warning(f"Duplicate key found: {key_str}")
        elif isinstance(value, ruamel.yaml.nodes.MappingNode):
            if merged[key_str] is None:
                merged[key_str] = value
            else:
                for k, v in value.items():
                    if not isinstance(k, ruamel.yaml.nodes.ScalarNode):
                        raise ValueError("Invalid key in child map: " + type(k).__name__)
                    if merged[key_str][k.value] is None:
                        merged[key_str][k.value] = v
                    else:
                        logging.warning(f"Duplicate key found: {k.value} in child map of {key_str}")

    return list(sorted({'(obj, ' + key + ')' if isinstance(key, ruamel.yaml.nodes.ScalarNode) else '(map, ' + key + ')' : value for key, value in merged.items()}))   # sort by (obj, key) in first appearance

