def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_args = {}
    remaining_args = []

    # create matching dictionary so we can pigeonhole arguments
    possible_args = {
        key: parser.add_argument(key, help=parser.description)
        for key, parser in subparsers.items()
    }

    # We parse the arguments according to set order (if it exists).
    if 'SET' in possible_args:
        possible_args['SET'].dest = 'set'

    # Note that variables like 'args' are shadowed by possible_args. The latter
    # is our pointer to our argument collection dict.
    for arg in possible_args:
        possible_args[arg].completer = subparsers[arg].complete

    while unparsed_arguments:
        try:
            arg = unparsed_arguments.pop(0)
            if arg in possible_args:
                possible_args[arg].action('--', count=2)  # Corresponding value argument
                parsed_args[arg] = unparsed_arguments.pop(0)  # Process option
                remaining_args += unparsed_arguments
            else:
                remaining_args.append(arg)  # It's a positional argument
        except ValueError as e:
            print(f"Error parsing argument: {e}")

    return parsed_args, remaining_args

