def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty")

    if number == 0:
        return alphabet[0]

    digits = []

    while number > 0:
        digit = number % len(alphabet)
        digits.append(alphabet[digit])
        number //= len(alphabet)

    if padding is not None:
        digits = digits + ['0'] * (padding - len(digits))

    return ''.join(digits[::-1])

def int_to_string(number, alphabet, padding=None):
    """Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not all(isinstance(char, str) for char in alphabet):
        raise TypeError("Alphabet must be a list of strings.")

    if number < 0 or number >= len(alphabet):
        raise ValueError("Number is out of the range of the alphabet.")

    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise TypeError("Padding must be an integer or None.")

    result = ""
    while number > 0:
        next_digit = number % len(alphabet)
        result = alphabet[next_digit] + result
        number //= len(alphabet)

    if padding is not None:
        result = ("0" * padding) + result

    return result

