def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    if platform == 'this':
        is_windows = re.search(r'\bwin\b', platform, re.IGNORECASE)
        is_posix = re.search(r'\bposix\b', platform, re.IGNORECASE)
        if is_windows:
            return re.split((' ', '\t', '\n', '\r'), s)  # regular expression to split at spaces, tabs, newlines, carriage returns
        elif is_posix:
            return re.split((' ', '\t'), s)  # regular expression to split at spaces and tabs
        else:
            raise ValueError("Unrecognized platform '%s'" % platform)
    else:
        is_windows = bool(platform == 0)
        is_posix = bool(platform == 1)
        if is_windows:
            return re.split((' ', '\t', '\n', '\r'), s)  # regular expression to split at spaces, tabs, newlines, carriage returns
        elif is_posix:
            return re.split((' ', '\t'), s)  # regular expression to split at spaces and tabs
        else:
