from collections import defaultdict
from typing import Optional, Set

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if roots is None:
        roots = set()

    transitive = defaultdict(set)
    unprocessed = graph.subjects(predicate=prop)
    while unprocessed:
        subject = unprocessed.pop()
        triples = list(graph.triples((subject, prop, None)))
        for _, predicate_, object_ in triples:
            if object_ not in transitive:
                unprocessed.add(object_)
                transitive[object_] |= transitive[subject]
            if object_ not in roots:
                roots.add(object_)
    return roots

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    visited = set()
    root_set = set()

    def dfs(node):
        if node not in visited:
            visited.add(node)
            for child in node.triples((None, prop, None)):
                dfs(child[2])

    for triple in graph:
        if triple[0] in graph:
            dfs(triple[0])

    while visited:
        root = visited.pop()
        root_set.add(root)
        node_set = graph.triples((root, None, None))
        for child in node_set:
            visited.add(child[2])

    return root_set

