def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Any]] = None) -> Set[Any]:
    if roots is None:
        roots = set()
    for child, parent in graph.subject_objects(prop):
        if graph.value(child, RDFS.domain) is None or graph.value(parent, RDFS.domain) is None:
            continue
        if graph.value(child, RDFS.range) is None or graph.value(parent, RDFS.range) is None:
            continue
        if graph.value(parent, RDFS.isDefinedBy) is None or graph.value(child, RDFS.isDefinedBy) is None:
            continue
        if graph.value(parent, RDF.subClassOf) is not None and graph.value(child, RDF.subClassOf) is not None:
            child = (graph.value(parent, RDF.subClassOf), bNode())
            graph.add((child, RDF.subClassOf, parent))
        if graph.value(parent, SKOS.broader) is not None and graph.value child, SKOS.broader) is not None:
            child = (graph.value(parent, SKOS.broader), bNode())
            graph.add((child, SKOS.broader, parent))
        if child in graph.subjects(RDFS.domain):
            root = child
            graph.add((root, RDF.type, URIRef("http://example.org/IRIs/Class")))
            roots.add(root)
            find_roots(graph, prop, roots)
    return roots

def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """

    if roots is None:
        roots = set()

    def dfs(node):
        for child in graph.objects(node, prop):
            if child not in roots:
                roots.add(child)
                dfs(child)

    for node in graph.objects():
        dfs(node)

    return roots

