        if self.ambiguous:
            if new_dt.fold:
                if dt.fold:
                    self.ambiguous_count += 1
                else:
                    print(f"Folded datetime was already ambiguous, no new fold")
            else:
                if dt.fold:
                    self.ambiguous_count += 1
                    print(f"Folded datetime is new, setting new fold")
                else:
                    print("New datetime was not indeed ambiguous")
        else:
            if new_dt.fold:
                if not dt.fold:
                    print(f"Non-folding datetime was already new, no new fold")
                else:
                    print(f"Non-folding datetime is new, setting new fold")
            else:
                if not dt.fold:
