def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    last_end = 0
    in_code = False

    for i in range(len(text)):
        if text[i] == '<':
            in_code = True
        elif text[i] == '>':
            if not in_code:
                tag = text[last_end+1:i]
                tags.add(tag)
                last_end = i
        if replacer and in_code:
            pass
        elif replacer and text[i:i+4] == '<!--':
            last_end = i
            while text[i:i+4] != '-->':
                i += 1
            i += 1  # Skip -->
            in_code = False

    if replacer:
        replaced_text = text[:last_end] + replacer(text[last_end+1:])
    else:
        replaced_text = text

    return tags, replaced_text

