def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if text is None:
        raise ValueError("Text cannot be None")

    links = re.findall(r'\b(https?://\S+)\b', text)

    attribute_links = {
        '1': {'class': 'external-link', 'title': 'Link'},
        '2': {'class': 'internal-link', 'title': 'Internal Link'}
    }

    links_with_attributes = {key: text
                    for key, link in enumerate(links)
                    for attribute in attribute_links.keys()
                    if re.search(link, text.lower())
                    and not link.startswith('http')

    for key, attributes in links_with_attributes.items():
        new_text = text.replace(attributes, '<a href="' + attributes + '">' + attributes + '</a>')

    return new_text

