def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.

        Arguments:
            public_key (:class:`PublicKey`): The public key used to verify the signature
            doc (:class:`Document`):The XML document to verify
            signature (:class:`Signature`): The signature to verify
    """

    if not public_key:
        raise ValueError("Public key is required. Please provide a public key.")

    if not doc:
        raise ValueError("Document is required. Please provide a valid XML document.")

    if not signature:
        raise ValueError("Signature is required. Please provide a valid signature.")

    try:
        verification_result = public_key.verify(doc, signature)
        return verification_result
    except InvalidSignatureError as e:
        print("Invalid signature: ", e)
        return False
    except DocumentError as e:
        print("Invalid document: ", e)
        return False

