    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise ValueError("The first parameter must be a dictionary")
    if not isinstance(val, (int, float, str, list, dict, AbstractElement)):
        raise ValueError("The second parameter must be a python data type or an AbstractElement object")
    if not isinstance(key, str) or not key:
        raise ValueError("The third parameter must be a non-empty string")
    if not keys:
        dic[key] = val
    else:
        nested_key = keys[0]
        if nested_key not in dic:
            dic[nested_key] = {}
        dict_insert(dic[nested_key], val, *keys[1:])

